content.content:
  margin-bottom: 6px;
}
h3 {
  font-size: 18px;
  margin-bottom: 4px;
}
.muted {
  color: var(--muted);
  margin: 0;
}
.docs-btn {
  font-family: var(--mono);
  font-size: 13px;
  color: var(--text);
  text-decoration: none;
  border: 1px solid var(--border);
  background: var(--card);
  padding: 10px 16px;
  border-radius: 8px;
}
.docs-btn:hover {
  border-color: var(--accent);
}
.main {
  display: flex;
  flex-direction: column;
  gap: 24px;
  margin-top: 32px;
}
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 28px 32px;
}
.title-code {
  font-family: var(--mono);
  font-size: 0.9em;
}
.cmd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 20px;
  margin-top: 16px;
  min-width: 0;
}
.cmd code {
  font-family: var(--mono);
  font-size: 15px;
  word-break: break-all;
}
.cmd.alt {
  background: var(--soft);
  margin-top: 0;
}
.cmd.compact {
  margin-top: 0;
  padding: 10px 16px;
}
.cmd-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
  margin-top: 12px;
}
.cmd-tag {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.cmd button {
  flex-shrink: 0;
  font-family: var(--mono);
  font-size: 13px;
  color: var(--muted);
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px 8px;
}
.cmd button:hover {
  color: var(--accent);
}
.step {
  margin-top: 20px;
}
.note {
  margin-top: 12px;
  background: var(--soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 20px;
  color: var(--muted);
  font-size: 14px;
}
.inline {
  font-family: var(--mono);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1px 6px;
  color: var(--text);
}
hr {
  border: none;
  border-top: 1px solid var(--border);
  margin: 28px 0;
}
.tip {
  color: var(--muted);
  font-size: 13px;
  margin: 12px 0 0;
}
.trouble {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
</style>

